using System.Net; using System.Net.Http.Json; using MarketBook.Application.Features.MarketPrices.Commands.CreateMarketPrice; using MarketBook.Application.Features.MarketPrices.Commands.UpdateMarketPrice; using MarketBook.Application.Features.MarketPrices.Queries.GetAllMarketPrices; using MarketBook.Application.Features.MarketPrices.Queries.GetMarketPriceById; using MarketBook.Integration.Tests.Infrastructure; namespace MarketBook.Integration.Tests.Features.MarketPrices;
/// <summary>EN: Integration tests for MarketPrice endpoints. FA: تست‌های Integration مربوط به Endpointهای MarketPrice.</summary>
[Collection(IntegrationTestCollection.Name)] public sealed class MarketPriceEndpointsTests{private readonly IntegrationTestFixture _fixture;
/// <summary>EN: Initializes tests. FA: تست‌ها را مقداردهی می‌کند.</summary>
public MarketPriceEndpointsTests(IntegrationTestFixture fixture){_fixture=fixture;} private static CreateMarketPriceRequest Request(string listingId,DateOnly? date=null)=>new(listingId,date??new DateOnly(2026,9,6),100m,110m,95m,108m,107m,100m,100m,90m,110m); [Fact] public async Task Create_And_Get_Should_Persist_Prices_And_Limits(){await _fixture.ResetMarketPricesAsync();string listingId=await _fixture.CreateMarketPriceListingAsync();HttpResponseMessage create=await _fixture.Client.PostAsJsonAsync("/api/v1/market-prices",Request(listingId));Assert.Equal(HttpStatusCode.Created,create.StatusCode);System.Text.Json.JsonElement created=await create.Content.ReadFromJsonAsync<System.Text.Json.JsonElement>();string id=created.GetProperty("id").GetString()!;GetMarketPriceByIdResponse? item=await _fixture.Client.GetFromJsonAsync<GetMarketPriceByIdResponse>($"/api/v1/market-prices/{id}");Assert.NotNull(item);Assert.Equal(90m,item.LowerLimit);Assert.Equal(110m,item.UpperLimit);Assert.Equal(108m,item.LastPrice);} [Fact] public async Task Duplicate_Listing_Date_Should_Return_Conflict(){await _fixture.ResetMarketPricesAsync();string listingId=await _fixture.CreateMarketPriceListingAsync();Assert.Equal(HttpStatusCode.Created,(await _fixture.Client.PostAsJsonAsync("/api/v1/market-prices",Request(listingId))).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await _fixture.Client.PostAsJsonAsync("/api/v1/market-prices",Request(listingId))).StatusCode);} [Fact] public async Task Invalid_Price_Range_Should_Return_BadRequest(){await _fixture.ResetMarketPricesAsync();string listingId=await _fixture.CreateMarketPriceListingAsync();CreateMarketPriceRequest request=new(listingId,new DateOnly(2026,9,6),100m,110m,95m,120m,107m,100m,100m,90m,110m);Assert.Equal(HttpStatusCode.BadRequest,(await _fixture.Client.PostAsJsonAsync("/api/v1/market-prices",request)).StatusCode);} [Fact] public async Task Missing_Listing_Should_Return_NotFound(){await _fixture.ResetMarketPricesAsync();string missing="01ARZ3NDEKTSV4RRFFQ69G5FAV";Assert.Equal(HttpStatusCode.NotFound,(await _fixture.Client.PostAsJsonAsync("/api/v1/market-prices",Request(missing))).StatusCode);} [Fact] public async Task Update_Should_Persist_New_Limits(){await _fixture.ResetMarketPricesAsync();string listingId=await _fixture.CreateMarketPriceListingAsync();HttpResponseMessage create=await _fixture.Client.PostAsJsonAsync("/api/v1/market-prices",Request(listingId));System.Text.Json.JsonElement created=await create.Content.ReadFromJsonAsync<System.Text.Json.JsonElement>();string id=created.GetProperty("id").GetString()!;UpdateMarketPriceRequest update=new(101m,112m,96m,111m,109m,100m,100m,95m,115m);Assert.Equal(HttpStatusCode.OK,(await _fixture.Client.PutAsJsonAsync($"/api/v1/market-prices/{id}",update)).StatusCode);GetMarketPriceByIdResponse? item=await _fixture.Client.GetFromJsonAsync<GetMarketPriceByIdResponse>($"/api/v1/market-prices/{id}");Assert.Equal(115m,item!.UpperLimit);Assert.Equal(111m,item.LastPrice);} [Fact] public async Task Pagination_Should_Normalize(){await _fixture.ResetMarketPricesAsync();string listingId=await _fixture.CreateMarketPriceListingAsync();await _fixture.Client.PostAsJsonAsync("/api/v1/market-prices",Request(listingId));GetAllMarketPricesResponse? page=await _fixture.Client.GetFromJsonAsync<GetAllMarketPricesResponse>("/api/v1/market-prices?page=0&pageSize=500");Assert.NotNull(page);Assert.Equal(1,page.Page);Assert.Equal(100,page.PageSize);Assert.Equal(1,page.TotalCount);}}
